import OpenAI from "openai";

const client = new OpenAI({
  apiKey: process.env.NAN_API_KEY,
  baseURL: "https://api.nan.builders/v1",
});

const img = await client.images.generate({
  model: "flux-2-klein",
  prompt: "Un faro al atardecer sobre acantilados",
  size: "1024x1024",
});
console.log(img.data[0].url);

import OpenAI from "openai";

const client = new OpenAI({
  apiKey: process.env.NAN_API_KEY,
  baseURL: "https://api.nan.builders/v1",
});

import fs from "node:fs";
const img = await client.images.edit({
  model: "flux-2-klein",
  image: fs.createReadStream("ref.png"),
  prompt: "Convierte la escena en invierno con nieve",
});
console.log(img.data[0].url);

post.description:
An authenticated web search tool for agents. Give it a query and it returns ranked results (title, URL, snippet, source), drawn from a hybrid of upstream search providers. Results come back through the NaN API, so your key never talks to a third-party search provider directly, and you never hold a provider key.

Set `fetch_content: true` to also extract the readable main text of the top results (adds latency). You supply only `query`; when `fetch_content` is `true` the server fetches page content **only** for the URLs the search returned, through a hardened anti-SSRF fetcher, so you cannot pass an arbitrary URL to fetch.

Limits are per API key and separate from the model endpoints, so searching does not consume your chat RPM budget or vice versa: 20 requests per minute, 3 concurrent, and 500 searches per day. Exceeding the per-minute or concurrency limit returns `429` `rate_limit_exceeded`; exhausting the daily quota returns `429` `insufficient_quota`. A `429` carries a `Retry-After` header. Repeated identical queries within ~15 minutes are served from a short-lived cache (`cached: true`); cached hits still count toward your rate and quota.

## Use it as an agent tool

Drop this OpenAI-style function schema into your model call's `tools` array. When the model emits a `web_search` tool call, invoke `POST /v1/search` with the arguments and feed the JSON response back as the tool result.

```json
{
  "type": "function",
  "function": {
    "name": "web_search",
    "description": "Search the public web and return relevant results (title, URL, snippet, and optional page content). Use it when the answer may depend on current events, recent developments, prices, release/version numbers, or facts you are not confident are up to date.",
    "parameters": {
      "type": "object",
      "properties": {
        "query": { "type": "string", "description": "The web search query." },
        "count": { "type": "integer", "description": "Number of results to return (1-20).", "minimum": 1, "maximum": 20, "default": 5 },
        "freshness": { "type": "string", "description": "Restrict results by recency: 'pd' (past day), 'pw' (past week), 'pm' (past month), 'py' (past year), or a 'YYYY-MM-DDtoYYYY-MM-DD' date range. Omit for no time filter." },
        "fetch_content": { "type": "boolean", "description": "When true, also fetch and include the readable text of the top results (slower). Default false returns snippets only.", "default": false }
      },
      "required": ["query"]
    }
  }
}
```

