const res = await fetch("https://api.nan.builders/v1/search", {
  method: "POST",
  headers: {
    Authorization: `Bearer ${process.env.NAN_API_KEY}`,
    "Content-Type": "application/json",
  },
  body: JSON.stringify({ query: "latest go release", count: 5, freshness: "pw" }),
});
const data = await res.json();
for (const r of data.results) console.log(r.title, r.url);

curl https://api.nan.builders/mcp \
  -H "Authorization: Bearer $NAN_API_KEY" \
  -H "Content-Type: application/json" \
  -d '{
    "jsonrpc": "2.0",
    "id": 1,
    "method": "tools/call",
    "params": {
      "name": "web_search",
      "arguments": { "query": "kubernetes 1.34 release", "count": 5 }
    }
  }'

{
  "mcpServers": {
    "nan": {
      "url": "https://api.nan.builders/mcp",
      "headers": {
        "Authorization": "Bearer sk-your-key-here"
      }
    }
  }
}
